-- Run with BEGIN / ROLLBACK. No purchase or external message is sent.
do $$
declare adm uuid; uid uuid; source_id uuid; gift_id uuid; oid uuid; lid uuid; result jsonb; token text; data jsonb;
begin
 select user_id into adm from public.user_roles where role='admin' limit 1;
 select id into uid from auth.users where not public.has_role(id,'admin') limit 1;
 if uid is null then raise exception 'A non-admin fixture is required'; end if;
 insert into public.orders(user_id,status,payment_status,is_preview) values(uid,'COMPLETED','PAID',false) returning id into source_id;
 insert into public.tracks(order_id,status,version,audio_url) values(source_id,'READY',1,'https://example.com/existing.mp3');
 update public.pricing_config set is_active=true,price_cents=1900,price_promo_cents=null where id in ('gift_digital_existing','gift_short_30');
 perform set_config('request.jwt.claims',json_build_object('sub',uid,'role','authenticated')::text,true);
 execute 'set local role authenticated';
 gift_id:=gen_random_uuid();
 data:=jsonb_build_object('product','digital','music_source','existing','source_order_id',source_id,'recipient_name','Fixture','sender_name','Fixture','dedication','Fixture','details','{}'::jsonb);
 perform public.save_musical_gift(gift_id,data,0);
 result:=public.musical_gift_action(gift_id,'submit');oid:=(result->>'checkout_order_id')::uuid;
 if oid is null then raise exception 'Missing checkout order'; end if;
 if (select production_order_id from public.musical_gifts where id=gift_id) is not null then raise exception 'Existing song incorrectly entered production'; end if;
 begin update public.orders set amount=1 where id=oid;raise exception 'Expected quote guard';exception when others then if sqlerrm<>'gift_order_mismatch' then raise;end if;end;
 begin update public.orders set payment_status='PAID' where id=oid;raise exception 'Expected payment authorization guard';exception when others then if sqlerrm<>'gift_payment_forbidden' then raise;end if;end;
 begin perform public.confirm_gift_stripe(oid,'cs_fixture_session_123',1900);raise exception 'Client can fake Stripe confirmation';exception when insufficient_privilege then null;end;
 update public.orders set payment_status='AWAITING_PIX',pix_receipt_url='Fixture private receipt' where id=oid;
 if (select status from public.musical_gifts where id=gift_id)<>'RECEIPT_SENT' then raise exception 'Receipt did not synchronize';end if;
 execute 'reset role';
 perform set_config('request.jwt.claims',json_build_object('sub',adm,'role','authenticated')::text,true);
 execute 'set local role authenticated';
 update public.orders set payment_status='PAID',status='COMPLETED' where id=oid;
 if (select payment_confirmed_at from public.musical_gifts where id=gift_id) is null then raise exception 'Payment did not synchronize';end if;
 perform public.musical_gift_action(gift_id,'publish','{"reviewed":true}');
 execute 'reset role';
 perform set_config('request.jwt.claims',json_build_object('sub',uid,'role','authenticated')::text,true);
 execute 'set local role authenticated';
 gift_id:=gen_random_uuid();
 data:=jsonb_build_object('product','short','music_source','new','duration_seconds',30,'has_card',false,'recipient_name','Fixture','sender_name','Fixture','details',jsonb_build_object('story','A short personalized story that is long enough.','style','pop','language','Português','music_type','homenagem'));
 perform public.save_musical_gift(gift_id,data,0);result:=public.musical_gift_action(gift_id,'submit');oid:=(result->>'checkout_order_id')::uuid;
 if (select production_order_id from public.musical_gifts where id=gift_id)<>oid then raise exception 'Music and commerce created duplicate orders';end if;
 if (public.musical_gift_action(gift_id,'submit')->>'checkout_order_id')::uuid<>oid then raise exception 'Submit was not idempotent';end if;
 execute 'reset role';
 begin insert into public.lyrics(order_id,version,title,body,is_approved) values(oid,'A','Fixture','A short song for you',false);raise exception 'Expected unpaid lyric guard';exception when others then if sqlerrm<>'gift_invalid_payment' then raise;end if;end;
 perform set_config('request.jwt.claims',json_build_object('sub',adm,'role','authenticated')::text,true);
 execute 'set local role authenticated';
 execute 'reset role';
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 execute 'set local role service_role';
 begin update public.orders set payment_status='PAID' where id=oid;raise exception 'Unrelated service endpoint can fake payment';exception when others then if sqlerrm<>'gift_payment_forbidden' then raise;end if;end;
 perform public.confirm_gift_stripe(oid,'cs_fixture_session_123',1900);
 update public.orders set payment_status='PAID',status='LYRICS_PENDING' where id=oid;
 execute 'reset role';
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 execute 'set local role service_role';
 if not public.claim_gift_lyrics(oid) then raise exception 'Generation lock not acquired';end if;
 if public.claim_gift_lyrics(oid) then raise exception 'Duplicate generation lock';end if;
 update public.musical_gifts set lyrics_generation_started_at=null where production_order_id=oid;
 execute 'reset role';
 perform set_config('request.jwt.claims',json_build_object('sub',adm,'role','authenticated')::text,true);
 execute 'set local role authenticated';
 begin perform public.claim_gift_lyrics(oid);raise exception 'Customer can claim server generation lock';exception when insufficient_privilege then null;end;
 execute 'reset role';
 begin insert into public.lyrics(order_id,version,title,body,is_approved) values(oid,'A','Fixture',repeat('Long word ',30),false);raise exception 'Expected lyric size guard';exception when others then if sqlerrm<>'gift_lyric_too_long' then raise;end if;end;
 insert into public.lyrics(order_id,version,title,body,is_approved) values(oid,'A','Fixture',E'Uma canção para lembrar\nUm carinho para guardar',false) returning id into lid;
 begin insert into public.tracks(order_id,status,version,audio_url,duration_seconds) values(oid,'READY',1,'https://example.com/short.mp3',29.5);
 -- One recording is sufficient to complete production without activating the gift.
 update public.orders set status='COMPLETED',music_ready_at=now() where id=oid;
 if (select count(*) from public.tracks where order_id=oid and status='READY')<>1 then raise exception 'One-track completion requires a second recording';end if;
 if (select status from public.musical_gifts where id=gift_id)='ACTIVE' then raise exception 'Completion bypassed gift release';end if;
 -- Optional second recording remains accepted, with the existing version constraints.
 insert into public.tracks(order_id,status,version,audio_url,duration_seconds) values(oid,'READY',2,'https://example.com/optional.mp3',29.5)
 on conflict(order_id,version) do update set audio_url=excluded.audio_url;
 if (select audio_url from public.tracks where order_id=oid and version=1)<>'https://example.com/short.mp3' then raise exception 'Optional recording replaced primary';end if;
raise exception 'Expected approval before audio';exception when others then if sqlerrm<>'gift_lyrics_approval_required' then raise;end if;end;
 begin update public.orders set status='MUSIC_GENERATING' where id=oid;raise exception 'Expected approval before production';exception when others then if sqlerrm<>'gift_lyrics_approval_required' then raise;end if;end;
 update public.orders set approved_lyric_id=lid,status='LYRICS_APPROVED' where id=oid;
 update public.lyrics set is_approved=true,approved_at=now() where id=lid;
 insert into public.tracks(order_id,status,version,audio_url,duration_seconds) values(oid,'READY',1,'https://example.com/short.mp3',29.5);
 execute 'set local role authenticated';
 begin perform public.musical_gift_action(gift_id,'publish','{"reviewed":true,"duration_checked":true,"audio_duration_seconds":41}');raise exception 'Expected final duration guard';exception when others then if sqlerrm<>'gift_audio_duration_invalid' then raise;end if;end;
 perform public.musical_gift_action(gift_id,'publish','{"reviewed":true,"duration_checked":true,"audio_duration_seconds":29.5}');
 select public_token into token from public.musical_gifts where id=gift_id;
 if public.get_musical_gift(token)->>'lyrics' is distinct from E'Uma canção para lembrar\nUm carinho para guardar' then raise exception 'Wrong approved lyrics on gift';end if;
 execute 'reset role';
 -- Full songs remain unrestricted by the short-song budget.
 insert into public.lyrics(order_id,version,title,body,is_approved) values(source_id,'A','Fixture',repeat('Normal full song ',100),false);
end $$;
